import { abs } from "@/lib/schema";
import { SITEMAP_IDS } from "@/content/sitemapSections";

// Sitemap index at /sitemap.xml, pointing to the section sitemaps generated by app/sitemap.ts.
export const dynamic = "force-static";

export function GET() {
  const lastmod = new Date().toISOString();
  const body = `<?xml version="1.0" encoding="UTF-8"?>
<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${SITEMAP_IDS.map((id) => `  <sitemap><loc>${abs(`/sitemap/${id}.xml`)}</loc><lastmod>${lastmod}</lastmod></sitemap>`).join("\n")}
</sitemapindex>
`;
  return new Response(body, { headers: { "Content-Type": "application/xml; charset=utf-8" } });
}
